SELECT DISTINCT(p.id) id,p.parent_id AS pid,p.perm_name AS title,p.perm_url AS url,p.level,p.cate,p.sort,p.code FROM safety_sys_role_perm rp INNER JOIN safety_sys_perm p ON rp.perm_id=p.id AND p.cate BETWEEN 1 AND 9 WHERE rp.role_id in
#{itemType}
ORDER BY p.level,p.sort

select r.id,r.role_name,r.role_desc,r.delete_falg
  from safety_sys_user_role t, safety_sys_user u,safety_sys_role r
 where t.user_id = u.id and t.role_id = r.id and u.emp_no = #{empNo}
